const MediumPrimaryInteractiveLoadingButton = () => {
    const { t } = useTranslation(ALL_NAMESPACES);
    const [loading, setLoading] = useState(false);

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (args.onClick) args.onClick(e);
      setLoading(true);
      setTimeout(() => {
        setLoading(false);
      }, 2000);
    };

    return (
        <Button size="md" variant="solid" loading={loading} onClick={handleClick}>
            {t("button.label")}
        </Button>
    );
};

