  const Component = renderAs === "svg" ? QRCodeSVG : QRCodeCanvas;

  return (
    <div className={classNames("wim-qr-code", styles.root, className)}>
      <Component
        value={value}
        size={size}
        level={level}
        bgColor={bgColor}
        fgColor={fgColor}
        marginSize={marginSize}
        imageSettings={imageSettings}
        aria-label={ariaLabel ?? value}
      />
    </div>
  );
};

