const ExclusiveList = function Render() {
  const { t } = useTranslation(ALL_NAMESPACES);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<{ id: number; action: string } | null>(null);
  const swipeActionRefs = useRef<Record<number, SwipeActionRef | null>>({});

  const handleAction = (id: number, action: string) => {
    setSelectedItem({ id, action });
    setDialogOpen(true);
  };

  const confirmAction = () => {
    if (selectedItem) {
      console.log(`Updated Task ${selectedItem.id} to ${selectedItem.action}`);
      swipeActionRefs.current[selectedItem.id]?.close();
    }
    setDialogOpen(false);
  };

  return (
    <>
      <SwipeableList exclusive>
        <List>
          {[1, 2, 3, 4, 5].map((i) => (
            <SwipeAction
              key={i}
              as="li"
              ref={(el) => { swipeActionRefs.current[i] = el; }}
              closeOnAction={false}
              leftActions={[
                {
                  icon: "CheckIcon",
                  label: "Start",
                  onClick: () => handleAction(i, "In Progress"),
                  intent: "success",
                },
              ]}
              rightActions={[
                {
                  icon: "BellIcon",
                  label: "Hold",
                  onClick: () => handleAction(i, "On Hold"),
                  intent: "warning",
                },
                {
                  icon: "TrashIcon",
                  label: "Cancel",
                  onClick: () => handleAction(i, "Cancelled"),
                  intent: "danger",
                },
              ]}
            >
              <ListItem title={`Task ${i}`} subtitle={t("story.swipe_subtitle_exclusive")} />
            </SwipeAction>
          ))}
        </List>
      </SwipeableList>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t("story.swipe_update_title")}</DialogTitle>
            <DialogDescription>
              {t("story.swipe_update_desc", { id: selectedItem?.id, action: selectedItem?.action })}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Stack direction="row" gap="sm" justify="end" style={{ width: "100%" }}>
              <Button variant="ghost" onClick={() => setDialogOpen(false)}>
                {t("action.cancel")}
              </Button>
              <Button 
                variant="solid"
                intent={selectedItem?.action === "Cancelled" ? "danger" : "default"}
                onClick={confirmAction}
              >
                {t("action.confirm")}
              </Button>
            </Stack>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

