import type { Meta, StoryObj } from "@storybook/react-vite";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import { ALL_NAMESPACES } from "../../i18nConstants";
import {
  AppShell,
  Box,
  Button,
  CommandPalette,
  CommandPaletteContent,
  CommandPaletteEmpty,
  CommandPaletteGroup,
  CommandPaletteInput,
  CommandPaletteItem,
  CommandPaletteList,
  ContextMenu,
  ContextMenuItem,
  Dialog,
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  Group,
  Header,
  Menubar,
  Popover,
  PopoverContent,
  PopoverTrigger,
  Sidebar,
  Stack,
  Table,
  Tag,
  Text,
  Title,
} from "wimui";

/**
 * 6 枚目の合成画面（T32 / T95 の候補 A）。**狙いはアプリの外枠とオーバーレイ**で、
 * `AppShell` / `Menubar` / `CommandPalette` / `ContextMenu` / `Drawer` / `Dialog` /
 * `Popover` はここまでの 5 枚が一度も使っていなかった。
 *
 * **題材に字幕の校閲を選んだ理由。** `Menubar` が自然に成立する形が web の管理画面には
 * ほとんど無く（デスクトップ的なエディタくらい）、字幕は**尺・話者・行の長さが最初から
 * 不揃い**なので、実在感のあるデータを作るのに嘘をつかなくて済む。
 *
 * **主役は cue の表**（DESIGN.md 必須ルール 1）。メニューバー・サイドバー・ステータス
 * バーはクロームなので、ルール 12 に従って声量を落としてある ── 面を持たせない、
 * primary を置かない、表の上に KPI タイルを並べない。
 */
const meta: Meta = {
  title: "Patterns/Captions",
  parameters: {
    layout: "fullscreen",
  },
};

export default meta;

type Cue = {
  id: string;
  tc: string;
  dur: string;
  /** 話者が拾えていない行が実際に混じる（DESIGN.md「不完全な行」） */
  speaker?: string;
  text: string;
  /**
   * その cue の言語（T105）。
   *
   * **素材の字幕は UI の言語と一致しない。** ここは複数言語が収録された音源を
   * 校閲する画面なので、日本語の行と英語の行が混在するのが正しい（flagged 行は
   * 「英語の長い行が読了速度を超える」ことを示す例なので、翻訳すると題材が壊れる）。
   * 一方 `.storybook/preview.ts` は UI 言語に連動して `html` / `body` の `lang` を
   * 書き換えるため、**放っておくと英語の行が `lang="ja"` を継承する**。
   *
   * 実害は 2 つ: ①**WCAG 3.1.2「部分の言語」は Level AA** ── スクリーンリーダーが
   * 誤った言語の音韻で読む ②`src/lang.scss` の `body[lang="en"]` / `[lang="pt"]` の
   * `hyphens: auto` が日本語行に、`body[lang="ja"]` の行分割規則が英語行に当たる。
   *
   * **axe では検出できない**（`valid-lang` は宣言済みの値の妥当性しか見ず、
   * 「外国語の一節に `lang` が無い」は文章の言語判定が要る）。だから明示する。
   */
  lang: "ja" | "en";
  /** 読了速度が速すぎる cue。校閲で最初に見る対象 */
  flagged?: boolean;
};

/**
 * 尺・話者・行長を意図的に不揃いにしている。等間隔のタイムコードや連番の話者名は
 * 「置き換え待ちのプレースホルダ」に見える（DESIGN.md 13）。
 */
const CUES: Cue[] = [
  { id: "0041", tc: "00:04:12.180", dur: "1.9s", speaker: "波多野", text: "潮が引くまで待て。", lang: "ja" },
  {
    id: "0042",
    tc: "00:04:14.060",
    dur: "4.2s",
    speaker: "Iris Ferreira",
    text: "The tide chart says 6:40, but the harbour master moved it twice this week already.",
    lang: "en",
    flagged: true,
  },
  { id: "0043", tc: "00:04:18.300", dur: "2.4s", text: "（無線のノイズ）", lang: "ja" },
  { id: "0044", tc: "00:04:20.740", dur: "3.1s", speaker: "陳 立文", text: "二番倉庫の鍵、まだ返してない。", lang: "ja" },
  {
    id: "0045",
    tc: "00:04:23.880",
    dur: "1.2s",
    speaker: "波多野",
    text: "それは明日でいい。",
    lang: "ja",
  },
  {
    id: "0046",
    tc: "00:04:25.100",
    dur: "5.6s",
    speaker: "Iris Ferreira",
    text: "I filed the incident report under the old vessel number, so it will not show up in the weekly export until someone re-keys it.",
    lang: "en",
    flagged: true,
  },
];

/** クロームのメニュー。項目は製品文脈のあるものだけに絞る（装飾で埋めない）。 */
const CueMenubar = () => {
  const { t } = useTranslation(ALL_NAMESPACES);
  return (
    <Menubar>
      <Menubar.Menu value="file">
        <Menubar.Trigger>{t("docs_stories_recipes:captions.menu_file")}</Menubar.Trigger>
        <Menubar.Content>
          <Menubar.Item>{t("docs_stories_recipes:captions.menu_file_import")}</Menubar.Item>
          <Menubar.Item>{t("docs_stories_recipes:captions.menu_file_export")}</Menubar.Item>
          <Menubar.Separator />
          <Menubar.Item>{t("docs_stories_recipes:captions.menu_file_conform")}</Menubar.Item>
        </Menubar.Content>
      </Menubar.Menu>
      <Menubar.Menu value="timing">
        <Menubar.Trigger>{t("docs_stories_recipes:captions.menu_timing")}</Menubar.Trigger>
        <Menubar.Content>
          <Menubar.Item>{t("docs_stories_recipes:captions.menu_timing_shift")}</Menubar.Item>
          <Menubar.Item>{t("docs_stories_recipes:captions.menu_timing_snap")}</Menubar.Item>
        </Menubar.Content>
      </Menubar.Menu>
    </Menubar>
  );
};

const CueRow = ({
  cue,
  onOpenDetail,
  onDiscard,
}: {
  cue: Cue;
  onOpenDetail: () => void;
  onDiscard: () => void;
}) => {
  const { t } = useTranslation(ALL_NAMESPACES);
  return (
    <ContextMenu
      asChild
      menu={
        <>
          <ContextMenuItem onClick={onOpenDetail}>
            {t("docs_stories_recipes:captions.row_menu_history")}
          </ContextMenuItem>
          <ContextMenuItem onClick={onDiscard}>
            {t("docs_stories_recipes:captions.row_menu_discard")}
          </ContextMenuItem>
        </>
      }
    >
      <Table.Row onClick={onOpenDetail}>
        {/* `label` はカード表示（`mobileCard`）でヘッダの代わりに出る。
            `Table` は列のメタデータを持たないので、ここで渡さないと
            カードは値だけが並んだ状態になる */}
        <Table.Cell label={t("docs_stories_recipes:captions.col_tc")}>
          <Text size="sm" nowrap>
            {cue.tc}
          </Text>
        </Table.Cell>
        <Table.Cell label={t("docs_stories_recipes:captions.col_dur")}>
          <Text size="sm" color="secondary" nowrap>
            {cue.dur}
          </Text>
        </Table.Cell>
        <Table.Cell label={t("docs_stories_recipes:captions.col_speaker")}>
          {cue.speaker ? (
            // 話者名にも `lang` を付ける（T105）。**これは近似**で、人名の言語は
            // 発話の言語と必ずしも一致しない（`Iris Ferreira` はポルトガル語系の
            // 名前だがこの行の発話は英語）。それでも **UI の言語を継承させるより
            // 確実に良い** ── ここでは字種が一致しており（`波多野` / `陳 立文` は
            // CJK で `lang="ja"`、`Iris Ferreira` はラテン文字で `lang="en"`）、
            // 継承のままだと en の UI で `波多野` が英語の音韻で読まれる。
            <Text size="sm" nowrap lang={cue.lang}>
              {cue.speaker}
            </Text>
          ) : (
            // 「話者不明」は UI の文言なので `t()` 経由＝ページの言語のままで正しい。
            // ここに `lang` を付けてはいけない（**鳴ってはいけない経路**）。
            <Text size="sm" color="text-tertiary" nowrap>
              {t("docs_stories_recipes:captions.speaker_unknown")}
            </Text>
          )}
        </Table.Cell>
        <Table.Cell label={t("docs_stories_recipes:captions.col_text")}>
