                      setChecked(next);
                    }}
                  >
                    <span
                      style={{
                        textDecoration: checked[i] ? "line-through" : "none",
                        // text-disabled は surface-variant 上で AA を割るため tertiary
                        color: checked[i]
                          ? "var(--wim-color-text-tertiary)"
                          : "inherit",
                      }}
                    >
                      {item}
                    </span>
                  </Checkbox>
                </div>
              ))}
            </Stack>

            {completedCount === total && (
              <Alert intent="success" title={t("checklist.btn_view")} />
            )}
          </Stack>
        </Card>
      </Center>
    );
  },
};

