const SignupForm = function Render() {
  const { t } = useTranslation(ALL_NAMESPACES);
  const [password, setPassword] = useState("");

  const calculateScore = (pwd: string): 0 | 1 | 2 | 3 | 4 => {
    if (!pwd) return 0;
    let s = 0;
    if (pwd.length > 8) s++;
    if (/[A-Z]/.test(pwd)) s++;
    if (/[0-9]/.test(pwd)) s++;
    if (/[^A-Za-z0-9]/.test(pwd)) s++;
    return s as 0 | 1 | 2 | 3 | 4;
  };

  return (
    <Center
      style={{
        minHeight: "100vh",
        backgroundColor: "var(--wim-color-surface-app)",
        padding: "var(--wim-spacing-2xl)",
      }}
    >
      <Card
        variant="outline"
        padding="xl"
        style={{
          width: "100%",
          maxWidth: "420px",
        }}
      >
        <Stack gap="xl">
          <Stack align="center" gap="sm">
            <Title tag="h2" size="xl" align="center">
              {t("signup.title")}
            </Title>
            <Text
              content={t("signup.subtitle")}
              color="text-secondary"
              size="sm"
              style={{ textAlign: "center" }}
            />
          </Stack>

          <form onSubmit={(e) => e.preventDefault()}>
            <Stack gap="lg">
              <Input
                id="signup-name"
                label={t("signup.name")}
                placeholder={t("signup.name_placeholder")}
                fullWidth
              />
              <Input
                id="signup-email"
                label={t("signup.email")}
                type="email"
                placeholder={t("signup.email_placeholder")}
                fullWidth
              />
              <Stack gap="xs">
                <PasswordInput
                  id="signup-password"
                  label={t("signup.password")}
                  fullWidth
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                {password && (
                  <PasswordStrength
                    score={calculateScore(password)}
                    showLabel
                  />
                )}
              </Stack>
              <Input
                id="signup-confirm"
                label={t("signup.confirm_password")}
                type="password"
                fullWidth
              />
              <Checkbox id="signup-terms">{t("signup.terms")}</Checkbox>
              <Button variant="solid" style={{ width: "100%" }}>
                {t("signup.btn")}
              </Button>
            </Stack>
          </form>

          <Stack direction="row" justify="center" gap="2xs">
            <Text
              content={t("signup.have_account")}
              size="sm"
              color="text-tertiary"
            />
            <Link href="#" style={{ fontSize: "var(--wim-font-size-sm)" }}>
              {t("signup.sign_in")}
            </Link>
          </Stack>
        </Stack>
      </Card>
    </Center>
  );
};

const MultiStepForm = function Render() {
  const { t } = useTranslation(ALL_NAMESPACES);
  const [step, setStep] = useState(0);
  const [isWide, setIsWide] = useState(
    () => typeof window !== "undefined" && window.matchMedia(WIDE).matches
  );

  React.useEffect(() => {
    const mq = window.matchMedia(WIDE);
    const handler = (e: MediaQueryListEvent) => setIsWide(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  const steps = [
    { title: t("multistep.step_account") },
    { title: t("multistep.step_profile") },
    { title: t("multistep.step_review") },
  ];

  const formData = {
    email: "john@example.com",
    name: "Priya Nair",
    company: "Acme Inc.",
    role: "Developer",
  };

  return (
    <Center
      style={{
        minHeight: "100vh",
        backgroundColor: "var(--wim-color-surface-app)",
        padding: "var(--wim-spacing-2xl)",
      }}
    >
      <Card
        variant="outline"
        padding="xl"
        style={{
          width: "100%",
          maxWidth: "560px",
        }}
      >
        <Stack gap="3xl">
          <Title tag="h2" size="lg" align="center">
            {t("multistep.title")}
          </Title>

          <Stepper
            steps={steps}
            current={step}
            direction={isWide ? "horizontal" : "vertical"}
          />

          <form onSubmit={(e) => e.preventDefault()}>
            {step === 0 && (
              <Stack gap="lg">
                <Input
                  id="ms-email"
                  label={t("multistep.email")}
                  type="email"
                  defaultValue={formData.email}
                  fullWidth
                />
                <Input
                  id="ms-password"
                  label={t("multistep.password")}
                  type="password"
                  defaultValue="••••••••"
                  fullWidth
                />
              </Stack>
            )}

            {step === 1 && (
              <Stack gap="lg">
                <Input
                  id="ms-name"
                  label={t("multistep.display_name")}
                  defaultValue={formData.name}
                  fullWidth
                />
                <Input
                  id="ms-company"
                  label={t("multistep.company")}
                  defaultValue={formData.company}
                  fullWidth
                />
                <Input
                  id="ms-role"
                  label={t("multistep.role")}
                  defaultValue={formData.role}
                  fullWidth
                />
              </Stack>
            )}

            {step === 2 && (
              <Stack gap="lg">
                <Title tag="h3" size="sm">
                  {t("multistep.review_title")}
                </Title>
                <DescriptionList>
                  <DescriptionListItem>
                    <DescriptionListTerm>{t("multistep.review_email")}</DescriptionListTerm>
                    <DescriptionListDetails>{formData.email}</DescriptionListDetails>
                  </DescriptionListItem>
                  <DescriptionListItem>
                    <DescriptionListTerm>{t("multistep.review_name")}</DescriptionListTerm>
                    <DescriptionListDetails>{formData.name}</DescriptionListDetails>
                  </DescriptionListItem>
                  <DescriptionListItem>
                    <DescriptionListTerm>{t("multistep.review_company")}</DescriptionListTerm>
                    <DescriptionListDetails>{formData.company}</DescriptionListDetails>
                  </DescriptionListItem>
                  <DescriptionListItem>
                    <DescriptionListTerm>{t("multistep.review_role")}</DescriptionListTerm>
                    <DescriptionListDetails>{formData.role}</DescriptionListDetails>
                  </DescriptionListItem>
                </DescriptionList>
              </Stack>
            )}
          </form>

          <Group justify="between">
            <Button
              variant="outline"
              onClick={() => setStep(Math.max(0, step - 1))}
              disabled={step === 0}
            >
              {t("multistep.btn_back")}
            </Button>
            {step < 2 ? (
              <Button
                variant="solid"
                onClick={() => setStep(step + 1)}
              >
                {t("multistep.btn_next")}
              </Button>
            ) : (
              <Button variant="solid">{t("multistep.btn_submit")}</Button>
            )}
          </Group>
        </Stack>
      </Card>
    </Center>
  );
};

