const ProgressChecklist = function Render() {
  const { t } = useTranslation(ALL_NAMESPACES);
  const [checked, setChecked] = useState([true, false, false, false, false]);
  const completedCount = checked.filter(Boolean).length;
  const total = checked.length;
  const items = [
    t("checklist.item_1"),
    t("checklist.item_2"),
    t("checklist.item_3"),
    t("checklist.item_4"),
    t("checklist.item_5"),
  ];

  return (
    <Center
      style={{
        minHeight: "100vh",
        backgroundColor: "var(--wim-color-surface-app)",
        padding: "var(--wim-spacing-2xl)",
      }}
    >
      <Card
        variant="outline"
        padding="xl"
        style={{
          width: "100%",
          maxWidth: "500px",
        }}
      >
        <Stack gap="2xl">
          <Stack gap="sm">
            <Title tag="h2" size="lg">
              {t("checklist.title")}
            </Title>
            <Text
              content={t("checklist.subtitle")}
              color="text-secondary"
              size="sm"
            />
          </Stack>

          <Stack gap="md">
            <Stack direction="row" justify="space-between" align="center">
              <Text
                content={`${completedCount} / ${total}`}
                size="sm"
                color="text-secondary"
              />
              <Text
                content={`${Math.round((completedCount / total) * 100)}%`}
                size="sm"
                style={{ fontWeight: 600 }}
              />
            </Stack>
            <Progress
              value={(completedCount / total) * 100}
              intent={completedCount === total ? "success" : "primary"}
              aria-label={t("checklist.title")}
            />
          </Stack>

          <Stack gap="sm">
            {items.map((item, i) => (
              <div
                key={i}
                style={{
                  padding: "var(--wim-spacing-md) var(--wim-spacing-lg)",
                  borderRadius: "var(--wim-radius-lg)",
                  background: checked[i]
                    ? "var(--wim-color-surface-variant)"
                    : "transparent",
                  border: "1px solid var(--wim-color-border-secondary)",
                  transition: "background 0.2s",
                }}
              >
                <Checkbox
                  id={`task-${i}`}
                  checked={checked[i]}
                  onChange={(e) => {
                    const next = [...checked];
                    next[i] = e.target.checked;
                    setChecked(next);
                  }}
                >
                  <span
                    style={{
                      textDecoration: checked[i] ? "line-through" : "none",
                      // text-disabled は surface-variant 上で AA を割るため tertiary
                      color: checked[i]
                        ? "var(--wim-color-text-tertiary)"
                        : "inherit",
                    }}
                  >
                    {item}
                  </span>
                </Checkbox>
              </div>
            ))}
          </Stack>

          {completedCount === total && (
            <Alert intent="success" title={t("checklist.btn_view")} />
          )}
        </Stack>
      </Card>
    </Center>
  );
};

