    return (
      <Card
        variant="outline"
        padding="xl"
        style={{
          width: "min(100vw - 2rem, 28rem)",
        }}
      >
        <form
          onSubmit={handleSubmit(() => {
            reset();
          })}
        >
          <Stack gap="lg">
            <FormField
              control={control}
              name="eventDate"
              render={({ field, error }) => (
                <DatePicker
                  {...valueFieldProps(field)}
                  label={t("rhf.label_event_date")}
                  error={error}
                  fullWidth
                  required
                />
              )}
            />
            <FormField
              control={control}
              name="notify"
              render={({ field, invalid }) => (
                <Switch {...checkedFieldProps(field)} error={invalid}>
                  {t("rhf.notify_reminders")}
                </Switch>
              )}
            />
            <FormField
              control={control}
              name="score"
              render={({ field, error }) => (
                <Rating
                  {...valueFieldProps(field)}
                  label={t("rhf.label_score")}
                  error={error}
                  required
                />
              )}
            />
            <Button
              type="submit"
              variant="solid"
              disabled={isSubmitting}
              style={{ width: "100%" }}
            >
              {t("rhf.submit")}
            </Button>
          </Stack>
        </form>
      </Card>
    );
  },
};

