/**
 * 採用ページの体裁。**主役は写真**で、色はその上に載る帯の設定。
 * 比率は排他の選択なので `ToggleGroup`（選択状態が要る）。
 */
export const PageStyle: Story = {
  render: function Render() {
    const { t } = useTranslation(ALL_NAMESPACES);
    const [ratio, setRatio] = useState(16 / 9);
    const [bandColor, setBandColor] = useState("#123f35");
    const [bandOpacity, setBandOpacity] = useState(68);
    const [headlineColor, setHeadlineColor] = useState("#f3ece1");

    /** 帯は写真の上に重なるので、不透明度は**アルファ**で持つ。
        `opacity` を使うと見出しの文字まで薄くなる。 */
    const band = (() => {
      const n = parseInt(bandColor.slice(1), 16);
      const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255];
      return `rgba(${r}, ${g}, ${b}, ${bandOpacity / 100})`;
    })();

    return (
      <Box p="2xl">
        <Grid
          cols={{ base: 1, lg: "minmax(0, 1fr) minmax(0, 18rem)" }}
          gap="2xl"
        >
          <Stack gap="md">
            <Stack gap="3xs">
              <Title tag="h2" size="sm">
                {t(ns("style_title"))}
              </Title>
              <Text size="xs" color="text-tertiary">
                {t(ns("style_hint"))}
              </Text>
            </Stack>
            <ImageCropper
              src="./images/sample-landscape.png"
              aspectRatio={ratio}
              applyLabel={t(ns("style_apply"))}
            />

            {/* **右の 3 つが効く先**。ここが無いと、色も不透明度も動かしても
                画面に何も起きない＝操作できるだけの飾りになる。
                写真の上に帯を敷き、その上に見出しを載せる実際の並び。 */}
            <Stack gap="2xs">
              <Text size="xs" color="text-tertiary">
                {t(ns("style_preview_label"))}
              </Text>
              <Box
                style={{
                  backgroundImage: "url(./images/sample-landscape.png)",
                  backgroundSize: "cover",
                  backgroundPosition: "center",
                  aspectRatio: "16 / 5",
                  display: "flex",
                  alignItems: "flex-end",
                }}
              >
                <Box p="lg" style={{ backgroundColor: band, width: "100%" }}>
                  {/* 見出しの色を確かめる面なので、色は state から当てる。 */}
                  <Text size="lg" weight="bold" style={{ color: headlineColor }}>
                    {t(ns("style_preview_headline"))}
                  </Text>
                </Box>
              </Box>
            </Stack>
          </Stack>

          <Stack gap="xl">
            {/* 排他の選択なので `ToggleGroup`。`ButtonGroup` は操作を束ねるもので
                選択状態を持たないため、3 つとも同じ見た目のまま残る。 */}
            <ToggleGroup
              label={t(ns("ratio_label"))}
              defaultValue="wide"
              size="sm"
              onChange={(v) =>
                setRatio(v === "square" ? 1 : v === "classic" ? 4 / 3 : 16 / 9)
              }
              options={[
                { label: t(ns("ratio_wide")), value: "wide" },
                { label: t(ns("ratio_classic")), value: "classic" },
                { label: t(ns("ratio_square")), value: "square" },
              ]}
            />

            <Stack gap="md">
              <ColorPicker
                label={t(ns("band_color_label"))}
                value={bandColor}
                onChange={(e) => setBandColor(e.target.value)}
                fullWidth
              />
              <Slider
                label={t(ns("band_opacity_label"))}
                min={0}
                max={100}
                step={4}
                value={bandOpacity}
                onChange={setBandOpacity}
              />
              <ColorInput
                label={t(ns("headline_color_label"))}
                value={headlineColor}
                onChange={(e) => setHeadlineColor(e.target.value)}
                fullWidth
              />
            </Stack>

            <Text size="xs" color="text-tertiary">
              {t(ns("style_contrast_note"))}
            </Text>
          </Stack>
        </Grid>
      </Box>
    );
  },
};

/**
 * 選考段階ごとの条件。**段階を切り替えたら条件も件数も入れ替わる**ので、
 * `SegmentedControl`（ビューの切り替え）が意味を持つ。切り替えても後ろが
 * 変わらないなら、それはただの選択肢＝ラジオで足りる。
 */
const QUERIES: Record<string, QueryGroup> = {
  applied: {
    id: "root",
    combinator: "and",
    not: false,
    rules: [
      { id: "a-1", field: "years", operator: ">=", value: 1 },
      { id: "a-2", field: "shift", operator: "contains", value: "early" },
    ],
  },
  screening: {
    id: "root",
    combinator: "and",
    not: false,
    rules: [
      { id: "s-1", field: "years", operator: ">=", value: 2 },
      { id: "s-2", field: "shift", operator: "contains", value: "early" },
      {
        id: "s-g1",
        combinator: "or",
        not: false,
        rules: [
          { id: "s-3", field: "commute", operator: "<=", value: 45 },
          { id: "s-4", field: "licence", operator: "=", value: true },
        ],
      },
    ],
  },
  interview: {
    id: "root",
    combinator: "and",
    not: false,
    rules: [
      { id: "i-1", field: "licence", operator: "=", value: true },
      { id: "i-2", field: "commute", operator: "<=", value: 30 },
    ],
  },
};

/**
 * 応募者の抽出。**主役は条件式**で、検索欄と選考段階の切替はその入口。
 * 件数は条件と内部整合させる（一致 ≤ 母数、段階が進むほど母数が減る）。
 */
export const TalentPool: Story = {
  render: function Render() {
    const { t } = useTranslation(ALL_NAMESPACES);
    const [stage, setStage] = useState("screening");

    /**
     * 段階を切り替えたら**後ろの内容が変わる**こと。変わらないなら
     * `SegmentedControl` を名乗る意味が無く、ただの選択肢＝ラジオで足りる。
     * 母数は選考が進むほど減る（184 → 41 → 12）。一致数はその部分集合。
     */
    const counts: Record<string, { matched: number; total: number }> = {
      applied: { matched: 62, total: 184 },
      screening: { matched: 27, total: 41 },
      interview: { matched: 9, total: 12 },
    };
    const { matched, total } = counts[stage];

    return (
      <Box p="2xl">
        <Stack gap="xl">
          <Stack gap="3xs">
            <Title tag="h2" size="sm">
              {t(ns("pool_title"))}
            </Title>
            <Text size="xs" color="text-tertiary">
              {t(ns("pool_hint"))}
            </Text>
          </Stack>

          {/* 入力の `width` は **max-width** として効くので（`--wim-input-width`）、
              flex 行に置くと内容幅（228px）まで縮み、placeholder が 2 行になって
              左のアイコンが 2 行目の高さに残る。列を作って `fullWidth` で埋める。 */}
          <Grid cols={{ base: 1, sm: "minmax(0, 22rem) auto" }} gap="md" align="end">
            <SmartSearchInput
              fullWidth
              placeholder={t(ns("pool_search_placeholder"))}
            />
            {/* 見ているデータの切り替え（即時反映）は `SegmentedControl`。
                `ToggleGroup` は「チェックボックス／ラジオのボタン版」＝**値を持つ
                入力**で、ツールバーや設定の側（この画面では PageStyle の切り抜き比率）。
                docs の design intent が両者をこう分けている。 */}
            <SegmentedControl
              value={stage}
              onChange={setStage}
              options={[
                { label: t(ns("stage_applied")), value: "applied" },
                { label: t(ns("stage_screening")), value: "screening" },
                { label: t(ns("stage_interview")), value: "interview" },
              ]}
              size="sm"
            />
          </Grid>

          {/* 段階ごとに条件そのものが入れ替わる（`key` で作り直す）。
              `defaultQuery` は非制御なので、`key` を変えないと段階を切り替えても
              前の条件が残り、「切り替わったのに何も起きない」画面になる。 */}
          <QueryBuilder
            key={stage}
            fields={[
              { name: "applied_on", label: t(ns("field_applied")), type: "date" },
              { name: "years", label: t(ns("field_years")), type: "number" },
              { name: "shift", label: t(ns("field_shift")), type: "string" },
              { name: "commute", label: t(ns("field_commute")), type: "number" },
              { name: "licence", label: t(ns("field_licence")), type: "boolean" },
            ]}
            /* `operator` は記号で渡す（`>=` / `<=` / `=`）。`greater_equal` の
               ような語を渡すと、演算子の Select が**空のまま黙って描画される**。 */
            defaultQuery={QUERIES[stage]}
          />

          {/* **`ButtonGroup`（joined）は使わない。** あれはセグメント状に
              「1 つの操作面」を作るもので、境目を共有して見える。ここの 2 つは
              別々の操作（条件を保存する / 結果を書き出す）で、押し間違いの
              コストも違うので、独立したボタンとして間を空ける。 */}
          <Grid
            cols={{ base: 1, sm: "auto minmax(0, 20rem)" }}
            gap="md"
            align="center"
          >
            <Text size="sm" color="text-secondary">
              {t(ns("pool_count"), { matched, total })}
            </Text>
            <Group gap="sm" justify="end">
              <Button size="sm" variant="ghost">
                {t(ns("pool_export"))}
              </Button>
              <Button size="sm" variant="outline">
                {t(ns("pool_save"))}
              </Button>
            </Group>
          </Grid>
        </Stack>
      </Box>
    );
  },
};

/**
 * 内定通知の返送。**主役は署名**なので、条件は上に短く置いて読ませる。
 */
export const Offer: Story = {
  render: function Render() {
    const { t } = useTranslation(ALL_NAMESPACES);

    return (
      <Box p="2xl">
        <Stack gap="xl">
          <Stack gap="3xs">
