            列そのものを canvas 幅に合わせないと、ボタンが 670px 離れて座る。 */}
        <Grid cols={{ base: "minmax(0, 1fr)", sm: "20rem" }}>
          <SignaturePad
            label={t(ns("offer_sign_label"))}
            width={320}
            height={160}
            canvasAriaLabel={t(ns("offer_sign_aria"))}
