        <Checkbox defaultChecked={false}>{t(ns("offer_confirm"))}</Checkbox>

        <Group gap="sm" align="center">
          <Button variant="solid">{t(ns("offer_submit"))}</Button>
          <Text size="xs" color="text-tertiary">
            {t(ns("offer_footnote"))}
          </Text>
        </Group>
      </Stack>
    </Box>
  );
};

