    return (
      <Center
        style={{
          minHeight: "100vh",
          backgroundColor: "var(--wim-color-surface-app)",
          padding: "var(--wim-spacing-2xl)",
        }}
      >
        <Stack
          gap="3xl"
          align="center"
          style={{ maxWidth: "560px", textAlign: "center" }}
        >
          {/*
            この 3 要素（淡い円のアイコン → 見出し → 説明）は `Result` そのもの。
            以前は 80px の円を <div> に直書きしていたが、それは当時「淡い円の上に
            アイコン」を描く部品が無かったため（T52 で孤島として記録し、T47⑥ で
            `Result` に `iconSurface` を足して解消した）。intent="warning" が
            --wim-color-warning-subtle を敷くので、手で色を指定するところは無くなる。
            title に Title を渡しているのは、`Result` の見出しが <div> だからで、
            ここはページの h1 が要る（下の Alert が h2 なので、抜けると heading-order）。
          */}
          <Result
            intent="warning"
            iconSurface
            icon={<Icon name="SettingsIcon" />}
            title={
              <Title tag="h1" size="xl" align="center">
                {t("maintenance.title")}
              </Title>
            }
            description={t("maintenance.desc")}
          />

          {/* h1 直後の見出しなので h2（axe: heading-order） */}
          <Alert intent="info" title={t("maintenance.eta_label")} titleTag="h2">
            {t("maintenance.eta")}
          </Alert>

          {/*
            `padding="xl"` は 22.4px（`--wim-spacing-3xl`）で、包んでいる
            `Stack gap="3xl"` と同じ値。以前は `md` ＝ **12px** で、**カードの
            内側が兄弟どうしの間隔より狭かった** ── 中身が枠に寄って見える。
            `Card` の padding は名前と同名のトークンを引かないので（`md` は
            `--wim-spacing-md` = 8px ではなく `--wim-spacing-xl` = 12px）、
            ここは値で合わせる。対応表は `Card.mdx` の「`padding` が実際に引く値」。
          */}
          <Card
            variant="outline"
            padding="xl"
            style={{
              width: "100%",
            }}
          >
            <Stack gap="md">
              <Text
                content={t("maintenance.notify_title")}
                style={{ fontWeight: 600 }}
              />
              <InputGroup>
                <Input
                  id="notify-email"
                  placeholder={t("maintenance.notify_placeholder")}
                  fullWidth
