    const brews = [
      { x: 2.1, y: 19.4, name: "L-2291" },
      { x: 2.4, y: 20.8, name: "L-2293" },
      { x: 2.6, y: 21.6, name: "L-2296" },
      { x: 3.1, y: 22.9, name: "L-2298" },
      { x: 3.4, y: 21.1, name: "L-2301" },
      { x: 2.9, y: 18.2, name: "L-2304" },
