                description: t(ns("chart_cupping_desc")),
                /* レーダーは正方形に描かれるので、広い列に置くと左右が余る。
                   幅を使うのは散布図のほうなので、そちらを 2 列にする。 */
                content: (
                  <RadarChart
                    data={cupping}
