export const Supply: Story = {
  render: function Render() {
    const { t } = useTranslation(ALL_NAMESPACES);

    const day = (iso: string) => new Date(`${iso}T00:00:00+09:00`);
    const tasks = [
      {
        id: "l-2291",
        label: "L-2291 Yirgacheffe",
        startDate: day("2026-08-03"),
