const Overview = () => {
  const { t } = useTranslation([...ALL_NAMESPACES, "audit"]);

  const variants = ["outline", "ghost"] as const;
  const intents = ["default", "danger"] as const;

  return (
    <AuditPage title={t("audit:input_family_title")}>
      {/* 1. Basic Comparison */}
      <ComparisonGrid title={t("audit:basic_comparison")}>
        <ComponentGroup label={t("audit:label_standard_inputs")} align="stretch" maxWidth="var(--wim-width-md)">
          <Input label={t("audit:label_standard_input")} placeholder={t("audit:sample_name_placeholder")} />
          <SearchInput label={t("audit:label_search_input")} placeholder={t("audit:sample_search_placeholder")} />
          <NumberInput label={t("audit:label_number_input")} placeholder={t("audit:sample_number_placeholder")} />
        </ComponentGroup>
        <ComponentGroup label={t("audit:label_otp_input")} align="stretch" maxWidth="var(--wim-width-md)">
          <OtpInput label={t("audit:label_otp_input")} length={6} />
        </ComponentGroup>
      </ComparisonGrid>

      {/* 2. Variant Comparison */}
      <ComparisonGrid title={t("audit:variant_comparison")}>
        {variants.map((variant) => (
          <ComponentGroup key={variant} label={t("audit:label_variant", { variant })} align="stretch" maxWidth="var(--wim-width-md)">
            <Input label={t("audit:label_variant", { variant })} variant={variant} placeholder={t("audit:sample_name_placeholder")} />
            <Textarea label={t("audit:label_variant", { variant })} variant={variant} placeholder={t("audit:sample_textarea_placeholder")} />
            {variant === "ghost" && (
              <InlineEdit label={t("audit:label_inline_edit_comparison")} defaultValue={t("audit:sample_inline_edit_placeholder")} />
            )}
          </ComponentGroup>
        ))}
      </ComparisonGrid>

      {/* 3. Intent Comparison */}
      <ComparisonGrid title={t("audit:intent_comparison")}>
        {intents.map((intent) => (
          <ComponentGroup key={intent} label={t("audit:label_intent", { intent })} align="stretch" maxWidth="var(--wim-width-md)">
            <InputAny label={t("audit:label_intent", { intent })} intent={intent as "default" | "danger"} placeholder={t("audit:sample_name_placeholder")} />
            <PasswordInputAny label={t("audit:label_intent", { intent })} intent={intent as "default" | "danger"} />
            <SmartSearchInput label={t("audit:label_intent", { intent })} intent={intent as "default" | "danger"} placeholder={t("audit:sample_smart_search_ai")} />
            <PromptInput label={t("audit:label_intent", { intent })} error={intent === "danger" ? t("audit:label_error_message") : undefined} placeholder={t("audit:sample_prompt_ai")} />
            <Combobox label={t("audit:label_intent", { intent })} options={[{ label: t("audit:label_option_1"), value: "1" }]} error={intent === "danger" ? t("audit:label_error_message") : undefined} placeholder={t("audit:sample_combobox_placeholder")} />
            <TagInput label={t("audit:label_intent", { intent })} defaultValue={[t("audit:sample_tag_a")]} error={intent === "danger" ? t("audit:label_error_message") : undefined} placeholder={t("audit:sample_tag_input_placeholder")} />
            <Select label={t("audit:label_intent", { intent })} options={[{ label: t("audit:label_option_1"), value: "1" }]} error={intent === "danger" ? t("audit:label_error_message") : undefined} placeholder={t("audit:sample_select_placeholder")} />
            <MultiSelect label={t("audit:label_intent", { intent })} options={[{ label: t("audit:label_option_1"), value: "1" }]} error={intent === "danger" ? t("audit:label_error_message") : undefined} placeholder={t("audit:sample_multi_select_placeholder")} />
          </ComponentGroup>
        ))}
      </ComparisonGrid>

      {/* 4. Specialized & AI Inputs */}
      <ComparisonGrid title={t("audit:specialized_inputs")}>
        <ComponentGroup label={t("audit:specialized_inputs")} align="stretch" maxWidth="var(--wim-width-md)">
          <PromptInput label={t("audit:label_ai_prompt")} placeholder={t("audit:sample_prompt_ai")} />
          <SmartSearchInput label={t("audit:label_ai_smart_search")} placeholder={t("audit:sample_smart_search_ai")} />
          <ColorPicker label={t("audit:label_color_picker")} />
          <ColorInput label={t("audit:label_color_input_hex")} fullWidth />
          <TagInput 
            label={t("audit:label_tag_input_freeform")} 
            defaultValue={[t("audit:sample_tag_a"), t("audit:sample_tag_b")]} 
            placeholder={t("audit:sample_tag_input_placeholder")}
          />
          <MultiSelect 
            label={t("audit:label_multi_select_selection")} 
            options={[
              { label: t("audit:label_option_1"), value: "1" },
