  { name: "Group C", value: 300 },
  { name: "Group D", value: 200 },
];

const scatterData = [
  { x: 100, y: 200, z: 200, name: "A" },
  { x: 120, y: 100, z: 260, name: "B" },
  { x: 170, y: 300, z: 400, name: "C" },
  { x: 140, y: 250, z: 280, name: "D" },
